def compute(vars):
    granted_awards = vars["v1"]
    grant_date_fair_value = vars["v2"]
    value = granted_awards * grant_date_fair_value

    return {
        "value": value,
        "trace": {
            "granted_awards": granted_awards,
            "grant_date_fair_value": grant_date_fair_value,
            "value": value,
            "output_meta": {
                "currency": "USD",
                "scale": "ones",
                "unit": "currency"
            }
        }
    }
